`}</style>
  );
}
export const galleryStyle = (height: number, style?: CSSProperties) =>
  ({
    "--z-ag-height": `${height}px`,
    "--z-ag-mobile-height": `${Math.min(height, 560)}px`,
    ...style,
  }) as CSSProperties;

"use client";
import { useState, type ReactNode } from "react";
import { motion } from "motion/react";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryIndex,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface PhotoStackGalleryItem extends GalleryInternalItem {}
export interface PhotoStackGalleryProps extends GalleryInternalProps {
  items: readonly PhotoStackGalleryItem[];
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  title?: ReactNode;
  description?: ReactNode;
  duration?: number;
  thumbSize?: number;
  curviness?: number;
  stagger?: number;
}
/** Persistent image nodes move between the compact stack, thumbnail rail and feature frame. */
export function PhotoStackGallery(props: PhotoStackGalleryProps) {
  const {
    items,
    open: controlledOpen,
    defaultOpen = false,
    onOpenChange,
    title = "Field Kit",
    description,
    duration = 0.8,
    thumbSize = 82,
    curviness = 8,
    stagger = 0.035,
    height = 640,
    label = "Photo stack gallery",
    className = "",
    style,
    renderCaption,
    onSelect,
  } = props;
  const env = useGalleryEnvironment();
  const { current, choose } = useGalleryIndex(props);
  const [internalOpen, setOpen] = useState(defaultOpen);
  const open = controlledOpen ?? internalOpen;
  const changeOpen = (next: boolean) => {
    if (controlledOpen === undefined) setOpen(next);
    onOpenChange?.(next);
  };
  const mobile = env.size.width < 600;
  const mainW = Math.min(env.size.width * (mobile ? 0.76 : 0.36), 450);
  const mainH = Math.min(env.size.height * (mobile ? 0.48 : 0.72), mainW * 1.25);
  const thumb = Math.min(thumbSize, mobile ? 58 : 90);
  const inactive = items.map((_, i) => i).filter((i) => i !== current);
  return (
    <div
      ref={env.ref}
      className={`z-ag z-ag-stack ${className}`}
      data-gallery="photo-stack-gallery"
      data-open={open}
      data-index={current}
      style={galleryStyle(height, style)}
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          changeOpen(false);
          env.ref.current?.querySelector<HTMLButtonElement>('[data-stack-index="0"]')?.focus();
        }
        if (open && ["ArrowRight", "ArrowDown", "ArrowLeft", "ArrowUp"].includes(event.key)) {
          event.preventDefault();
          choose(current + (event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1));
        }
      }}
      role="region"
      aria-label={label}
    >
      <GalleryInternalStyles />
      {open && (
        <>
          <div
            style={{
              position: "absolute",
              left: mobile ? "8%" : "35%",
              top: mobile ? "9%" : "35%",
              width: mobile ? "78%" : "24%",
              zIndex: 2,
            }}
          >
            <h2 style={{ fontSize: mobile ? 28 : 42, fontWeight: 400, margin: "0 0 12px" }}>
              {title}
            </h2>
            <div style={{ fontSize: 13, lineHeight: 1.6, color: "#666" }}>{description}</div>
            <p style={{ fontSize: 13 }}>
              {items[current] && (renderCaption?.(items[current], current) ?? items[current].title)}
            </p>
          </div>
          <button
            data-gallery-control
            type="button"
            aria-label="Close gallery"
            onClick={() => {
              changeOpen(false);
              env.ref.current?.querySelector<HTMLButtonElement>('[data-stack-index="0"]')?.focus();
            }}
            style={{
              position: "absolute",
              right: 24,
              top: 20,
              zIndex: 30,
              border: 0,
              borderRadius: "50%",
              width: 40,
              height: 40,
              background: "#ddd",
              fontSize: 24,
            }}
          >
            ×
          </button>
          <span className="z-ag-hint" style={{ top: 24, bottom: "auto" }} role="status">
            {String(current + 1).padStart(2, "0")} / {String(items.length).padStart(2, "0")}
          </span>
        </>
      )}
      {items.map((item, i) => {
        const active = i === current;
        const thumbIndex = inactive.indexOf(i);
        const width = open ? (active ? mainW : thumb) : Math.min(env.size.width * 0.47, 230);
        const imgHeight = open ? (active ? mainH : thumb * 1.25) : width * 1.25;
        const left = open
          ? active
            ? mobile
              ? (env.size.width - mainW) / 2
              : env.size.width - mainW - 48
            : mobile
              ? 24 + thumbIndex * (thumb + 9)
              : 32
          : env.size.width / 2 - width / 2 + (i - (items.length - 1) / 2) * 13;
        const top = open
          ? active
            ? mobile
              ? env.size.height * 0.34
              : (env.size.height - mainH) / 2
            : mobile
              ? env.size.height - thumb * 1.25 - 24
              : 60 + thumbIndex * (thumb * 1.25 + 10)
          : env.size.height / 2 - imgHeight / 2;
        return (
          <motion.button
            key={item.id}
            layout
            data-stack-index={i}
            type="button"
            aria-label={open ? `View ${item.title ?? `image ${i + 1}`}` : "Open photo gallery"}
            aria-pressed={open && active}
            onClick={() => {
              if (!open) {
                choose(i);
                changeOpen(true);
              } else {
                choose(i);
                onSelect?.(item, i);
              }
            }}
            transition={{
              layout: {
                duration: env.reduced ? 0 : duration,
                delay: env.reduced ? 0 : i * stagger,
                ease: [0.22, 1, 0.36, 1],
              },
            }}
            style={{
              position: "absolute",
              left,
              top,
              width,
              height: imgHeight,
              rotate: open ? 0 : (i - (items.length - 1) / 2) * curviness,
              border: 0,
              padding: 0,
              borderRadius: open && active ? 32 : 10,
              overflow: "hidden",
              zIndex: open ? (active ? 10 : 20) : i + 1,
              cursor: "pointer",
              background: "#d0ceca",
            }}
          >
            <GalleryInternalImage item={item} />
          </motion.button>
        );
      })}
      {!items.length && <div className="z-ag-empty">No images</div>}
      {!open && (
        <span className="z-ag-hint" style={{ left: "50%", transform: "translateX(-50%)" }}>
          Click to explore
        </span>
      )}
    </div>
  );
}
